'use strict';
(()=>{
 const $=id=>document.getElementById(id);
 const definitions=[['sauna-size',['S','M','L']],['sauna-storage',['No','Yes']],['sauna-roof',['Flat','Single slope','Gable']],['terrace-depth',['600','1200']],['window-width',['600','900','1200']]];
 for(const [id,labels]of definitions){
  const el=$(id),check=el.type==='checkbox',row=document.createElement('div');row.className='choice-row'+(id==='sauna-roof'?' roof':'');row.role='radiogroup';row.setAttribute('aria-labelledby',id+'-label');const label=document.querySelector('label[for="'+id+'"]')||el.closest('label');label.id=id+'-label';if(check){label.after(el);label.classList.remove('toggle-line');}el.classList.add('native-choice');el.tabIndex=-1;el.setAttribute('aria-hidden','true');el.after(row);
  const sync=()=>{for(const [i,b]of [...row.children].entries()){const on=check?el.checked===Boolean(i):el.selectedIndex===i;b.setAttribute('aria-checked',on);b.tabIndex=on?0:-1;}};
  labels.forEach((text,i)=>{const b=document.createElement('button');b.type='button';b.role='radio';b.textContent=text;b.dataset.value=check?String(Boolean(i)):el.options[i].value;b.onclick=()=>{if(check)el.checked=Boolean(i);else el.selectedIndex=i;sync();el.dispatchEvent(new Event('change',{bubbles:true}));};b.onkeydown=e=>{if(!['ArrowRight','ArrowLeft','ArrowUp','ArrowDown','Home','End'].includes(e.key))return;e.preventDefault();const j=e.key==='Home'?0:e.key==='End'?labels.length-1:(i+(['ArrowLeft','ArrowUp'].includes(e.key)?-1:1)+labels.length)%labels.length;row.children[j].click();row.children[j].focus();};row.append(b);});sync();el.addEventListener('change',sync);
 }
 $('facade').classList.add('native-choice');$('facade').tabIndex=-1;const sample=document.createElement('div');sample.className='material-sample';sample.textContent='Vertical timber';$('facade').after(sample);
 const appearance=document.createElement('div');appearance.className='appearance';appearance.innerHTML='<label for="appearance">Appearance</label><select id="appearance"><option value="arctic">White model</option><option value="materials">Materials</option></select>';document.querySelector('.view-switch').before(appearance);
 const product=document.createElement('section');product.id='customer-product';product.className='customer-page';product.hidden=true;product.innerHTML='<p>OBTP / SAUNA</p><h1>A place to slow down.</h1><p class="customer-note">A modular sauna with a small entrance hall, outdoor shower and optional storage. Choose the size and details that suit your space.</p><div class="photo-empty" role="img" aria-label="Reserved exterior photograph"></div><div class="photo-grid"><div class="photo-empty" role="img" aria-label="Reserved interior photograph"></div><div class="photo-empty" role="img" aria-label="Reserved material photograph"></div></div><button id="product-config">Configure your sauna.</button>';document.body.append(product);
 const drawings=document.createElement('section');drawings.id='customer-drawings';drawings.className='customer-page';drawings.hidden=true;drawings.innerHTML='<h1>Your drawings.</h1><p>Plan, two sections, window schedule and reserved construction details.</p><div class="drawing-actions"><a id="pdf-download" download>Download PDF</a><a id="pdf-open" target="_blank" rel="noopener">Open PDF</a></div><iframe id="pdf-preview" class="pdf-stage" title="A3 drawing layout"></iframe>';document.body.append(drawings);
 window.OBTPCustomerView=(value)=>{const section=value===true?'info':value===false?'config':value;for(const [id,key]of [['configurator','config'],['customer-information','info'],['customer-product','product'],['customer-drawings','drawings']])$(id).hidden=section!==key;window.scrollTo(0,0);if(section==='drawings')window.OBTPUpdatePDF?.();};$('product-config').onclick=()=>OBTPCustomerView('config');$('back-config').onclick=()=>OBTPCustomerView('config');
 window.OBTPUpdatePDF=()=>{const state=window.OBTPStudioV3;if(!state)return;const s=state.selection,key=`sauna-${s.size}-${s.storage?'storage':'open'}-r${s.roof}-t${s.terrace}-w${s.window}-f${s.facade}`;const url='generated/'+key+'.pdf?build='+state.sourceRevision;for(const id of ['pdf-download','pdf-open'])$(id).href=url;if($('pdf-preview').dataset.key!==key){$('pdf-preview').src=url;$('pdf-preview').dataset.key=key;}};
})();
